import { customAlphabet } from 'nanoid';

// random.ts owns the format of every application-generated random value, one named method per purpose, so reviewing
// randomness means reading this file. Callers never choose alphabets or lengths.

/** Use cases declare `random: Random` in their `deps`; tests supply fixed values. */
export interface Random {
  /** 32 characters from `0-9a-z`, generated by Nano ID. A lookup key, not a credential. */
  sessionId(): string;
  /** 32 cryptographically secure random bytes as unpadded base64url (43 characters, never containing `.`). */
  sessionSecret(): string;
}

const sessionId = customAlphabet('0123456789abcdefghijklmnopqrstuvwxyz', 32);

/** The production implementation; request entry points supply it as `deps.random`. */
export const random: Random = {
  sessionId,
  sessionSecret() {
    return Buffer.from(crypto.getRandomValues(new Uint8Array(32))).toString('base64url');
  },
};
